#include <math.h>
#include <stdio.h>
#include "hi_core.h"
#include "hi_baseline.h"      /* Generated by tools/export_baseline_header.py */
#include "hi_test_vectors.h"  /* Generated from stored CWRU windows; not committed. */

static int check_window(const float *window, const float expected[HI_FEATURE_COUNT], float expected_hi) {
    float real[HI_WINDOW_SIZE], imag[HI_WINDOW_SIZE]; hi_features_t features; unsigned int i;
    if (hi_compute_features(window, real, imag, &features) != 0) return 1;
    for (i = 0u; i < HI_FEATURE_COUNT; ++i)
        if (fabsf(features.value[i] - expected[i]) > 1e-4f) { printf("feature %u mismatch\n", i); return 1; }
    if (fabsf(hi_zscore_mean(&features, HI_BASELINE_MEAN, HI_BASELINE_STD) - expected_hi) > 1e-4f) return 1;
    return 0;
}
int main(void) {
    int initialized = 0; float first, second;
    if (check_window(HI_TEST_WINDOW_0, HI_EXPECTED_FEATURES_0, HI_EXPECTED_HI_0)) return 1;
    if (check_window(HI_TEST_WINDOW_1, HI_EXPECTED_FEATURES_1, HI_EXPECTED_HI_1)) return 1;
    first = hi_ema(HI_EXPECTED_HI_0, 0.0f, &initialized);
    second = hi_ema(HI_EXPECTED_HI_1, first, &initialized);
    if (fabsf(first - HI_EXPECTED_EMA_0) > 1e-4f || fabsf(second - HI_EXPECTED_EMA_1) > 1e-4f) return 1;
    puts("C/Python HI conformance passed"); return 0;
}
